<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f3f5f9;
        --surface: #ffffff;
        --surface-2: #f8fafc;
        --text: #132238;
        --muted: #5e6b7d;
        --border: #d8e0ea;
        --accent: #2563eb;
        --accent-hover: #1d4ed8;
        --danger: #dc2626;
        --danger-hover: #b91c1c;
        --shadow: 0 20px 60px -28px rgba(15, 23, 42, 0.35);
        --radius-xl: 28px;
        --radius-lg: 20px;
        --radius-md: 14px;
        --focus: #0f62fe;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-height: 100%;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #ffffff 0, #eef3fb 38%, var(--bg) 100%);
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--surface);
        border: 1px solid var(--border);
        transform: translateY(-140%);
        transition: transform 0.2s ease;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 5rem 1.25rem 2rem;
      }

      .preview-shell {
        width: min(100%, 760px);
        background: var(--surface);
        border: 1px solid var(--border);
        backdrop-filter: blur(12px);
        border-radius: 32px;
        box-shadow: var(--shadow);
        padding: clamp(1.25rem, 2.5vw, 2rem);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.45rem 0.8rem;
        border-radius: 999px;
        background: #eaf2ff;
        color: #1d4ed8;
        font-weight: 700;
        font-size: 0.875rem;
        letter-spacing: 0.01em;
      }

      h1 {
        margin: 1rem 0 0.5rem;
        font-size: clamp(2rem, 4vw, 3.25rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .lede {
        margin: 0;
        color: var(--muted);
        max-width: 56ch;
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .image-card {
        margin-top: 1.5rem;
        padding: 1rem;
        border-radius: var(--radius-xl);
        background: var(--surface);
        border: 1px solid var(--border);
      }

      .image-frame {
        border-radius: calc(var(--radius-xl) - 8px);
        overflow: hidden;
        background: linear-gradient(180deg, #dbeafe 0%, #bfdbfe 100%);
      }

      .image-frame img {
        display: block;
        width: 100%;
        height: auto;
        aspect-ratio: 16 / 10;
        object-fit: cover;
      }

      .image-meta {
        display: grid;
        gap: 0.5rem;
        grid-template-columns: 1fr auto;
        align-items: center;
        padding: 1rem 0.25rem 0.25rem;
      }

      .image-meta h2 {
        margin: 0;
        font-size: 1.1rem;
        line-height: 1.3;
      }

      .image-meta p {
        grid-column: 1 / -1;
        margin: 0;
        color: var(--muted);
        line-height: 1.5;
      }

      .trigger {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: var(--danger);
        color: white;
        font: inherit;
        font-weight: 700;
        padding: 0.85rem 1.2rem;
        cursor: pointer;
        box-shadow: 0 10px 24px -16px rgba(220, 38, 38, 0.7);
        transition: transform 0.15s ease, background 0.15s ease;
      }

      .trigger:hover {
        background: var(--danger-hover);
        transform: translateY(-1px);
      }

      .trigger:focus-visible,
      .dialog button:focus-visible,
      .dialog [type="submit"]:focus-visible {
        outline: 3px solid transparent;
        box-shadow:
          0 0 0 3px var(--surface),
          0 0 0 6px var(--focus);
      }

      dialog {
        border: 0;
        border-radius: 24px;
        padding: 0;
        width: min(92vw, 460px);
        color: var(--text);
        box-shadow: var(--shadow);
        background: var(--surface);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.55);
        backdrop-filter: blur(4px);
      }

      .dialog {
        padding: 1.25rem;
      }

      .dialog-header {
        display: flex;
        align-items: flex-start;
        gap: 1rem;
      }

      .dialog-icon {
        flex: 0 0 auto;
        width: 2.75rem;
        height: 2.75rem;
        border-radius: 999px;
        display: grid;
        place-items: center;
        color: #b91c1c;
        background: #fee2e2;
      }

      .dialog-icon svg {
        width: 1.25rem;
        height: 1.25rem;
      }

      .dialog h2 {
        margin: 0;
        font-size: 1.25rem;
        line-height: 1.25;
      }

      .dialog p {
        margin: 0.65rem 0 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 1.5rem;
      }

      .secondary,
      .primary {
        appearance: none;
        border-radius: 999px;
        border: 1px solid var(--border);
        padding: 0.85rem 1.15rem;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition: background 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
      }

      .secondary {
        background: var(--surface-2);
        color: var(--text);
      }

      .secondary:hover {
        background: #eef3f9;
      }

      .primary {
        background: var(--danger);
        color: white;
        border-color: var(--danger);
      }

      .primary:hover {
        background: var(--danger-hover);
        border-color: var(--danger-hover);
        transform: translateY(-1px);
      }

      @media (max-width: 640px) {
        .image-meta {
          grid-template-columns: 1fr;
        }

        .dialog-actions {
          justify-content: stretch;
        }

        .dialog-actions > * {
          flex: 1 1 100%;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-2: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --accent: ButtonText;
          --accent-hover: ButtonText;
          --danger: ButtonText;
          --danger-hover: ButtonText;
          --focus: Highlight;
        }

        .preview-shell,
        .image-card,
        dialog,
        .secondary,
        .primary,
        .trigger {
          forced-color-adjust: auto;
          border: 1px solid ButtonBorder;
          box-shadow: none;
        }

        dialog::backdrop {
          background: CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>

    <script>
      function App() {
        return `
          <main id="main">
            <section class="preview-shell" aria-labelledby="page-title">
              ${PageHeader()}
              ${ImageCard()}
            </section>
          </main>
          ${DeleteDialog()}
        `;
      }

      function PageHeader() {
        return `
          <span class="eyebrow">Library preview</span>
          <h1 id="page-title">Sunlit studio portrait</h1>
          <p class="lede">Review the image before deciding whether to keep it in your library. The delete action opens a confirmation dialog so the choice is deliberate.</p>
        `;
      }

      function ImageCard() {
        return `
          <article class="image-card" aria-labelledby="image-title">
            <div class="image-frame">
              <img
                src="https://images.unsplash.com/photo-1521572267360-ee0c2909d518?auto=format&fit=crop&w=1600&q=80"
                alt="Portrait of a woman in a sunlit studio wearing a white shirt."
              />
            </div>
            <div class="image-meta">
              <h2 id="image-title">Studio portrait.jpg</h2>
              <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
                Delete image
              </button>
              <p>Added to your library on April 18, 2026.</p>
            </div>
          </article>
        `;
      }

      function DeleteDialog() {
        return `
          <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
            <form class="dialog" method="dialog">
              <div class="dialog-header">
                <div class="dialog-icon" aria-hidden="true">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                    <path d="M12 9v4"></path>
                    <path d="M12 17h.01"></path>
                    <path d="M10.3 4.5h3.4L21 16.6c.8 1.4-.2 3.2-1.8 3.2H4.8c-1.6 0-2.6-1.8-1.8-3.2L10.3 4.5z"></path>
                  </svg>
                </div>
                <div>
                  <h2 id="delete-title">Delete this image?</h2>
                  <p id="delete-desc">This will remove the image from your library and cannot be undone.</p>
                </div>
              </div>
              <div class="dialog-actions">
                <button class="secondary" value="cancel" autofocus>Cancel</button>
                <button class="primary" value="delete">Delete image</button>
              </div>
            </form>
          </dialog>
        `;
      }

      const app = document.getElementById('app');
      app.innerHTML = App();

      const dialog = document.getElementById('delete-dialog');
      const trigger = document.querySelector('.trigger');

      trigger.addEventListener('click', () => {
        dialog.showModal();
      });

      dialog.addEventListener('close', () => {
        trigger.focus();
      });
    </script>
  </body>
</html>
